16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Email;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    @Email
54	    private String email;
55	
56	    @Column(name = "registration_date")
57	    private LocalDate registrationDate;
58	
59	    @Column(name = "customer_code")
60	    private String customerCode;
61	
62	    @Column(name = "household_id")
63	    private String householdId;
64	
65	    @Column(name = "namesake_count")
66	    private Integer namesakeCount;
67	
68	    @Column(name = "bulk_signup_warning")
69	    private Boolean bulkSignupWarning;
70	
71	    @Column(name = "household_size")
72	    private Integer householdSize;
73	
74	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
75	    private Set<Pet> pets;
76	
77	    public String getAddress() {
78	        return this.address;
79	    }
80	
81	    public void setAddress(String address) {
82	        this.address = address;
83	    }
84	
85	    public String getCity() {
86	        return this.city;
87	    }
88	
89	    public void setCity(String city) {
90	        this.city = city;
91	    }
92	
93	    public String getTelephone() {
94	        return this.telephone;
95	    }
96	
97	    public void setTelephone(String telephone) {
98	        this.telephone = telephone;
99	    }
100	
101	    public String getEmail() {
102	        return this.email;
103	    }
104	
105	    public void setEmail(String email) {
106	        this.email = email == null ? null : email.toLowerCase();
107	    }
108	
109	    public LocalDate getRegistrationDate() {
110	        return this.registrationDate;
111	    }
112	
113	    public void setRegistrationDate(LocalDate registrationDate) {
114	        this.registrationDate = registrationDate;
115	    }
116	
117	    public String getCustomerCode() {
118	        return this.customerCode;
119	    }
120	
121	    public void setCustomerCode(String customerCode) {
122	        this.customerCode = customerCode;
123	    }
124	
125	    public String getHouseholdId() {
126	        return this.householdId;
127	    }
128	
129	    public void setHouseholdId(String householdId) {
130	        this.householdId = householdId;
131	    }
132	
133	    public Integer getNamesakeCount() {
134	        return this.namesakeCount;
135	    }
136	
137	    public void setNamesakeCount(Integer namesakeCount) {
138	        this.namesakeCount = namesakeCount;
139	    }
140	
141	    public Boolean getBulkSignupWarning() {
142	        return this.bulkSignupWarning;
143	    }
144	
145	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
146	        this.bulkSignupWarning = bulkSignupWarning;
147	    }
148	
149	    public Integer getHouseholdSize() {
150	        return this.householdSize;
151	    }
152	
153	    public void setHouseholdSize(Integer householdSize) {
154	        this.householdSize = householdSize;
155	    }
156	
157	    /**
158	     * The owner's name formatted as {@code 'LastName, FirstName'} from the stored names.
159	     */
160	    public String getDisplayName() {
161	        return this.getLastName() + ", " + this.getFirstName();
162	    }
163	
164	    /**
165	     * The owner's initials: the upper-cased first letters of firstName and lastName,
166	     * dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
167	     */
168	    public String getInitials() {
169	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
170	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
171	    }
172	
173	    /**
174	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is the
175	     * last two digits of the registrationDate year, e.g. {@code 'LON-SMI-0007-M26'}.
176	     */
177	    public String getMembershipNumber() {
178	        return this.customerCode + "-M" + String.format("%02d", this.registrationDate.getYear() % 100);
179	    }
180	
181	    /** Fixed city-to-region table used to derive an owner's locality. */
182	    private static final Map<String, String> CITY_REGION = Map.of(
183	        "Sydney", "NSW",
184	        "Melbourne", "VIC",
185	        "Brisbane", "QLD");
186	
187	    /**
188	     * The owner's locality: the canonical region derived from the city using the fixed
189	     * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
190	     * {@code Brisbane -> QLD}), or {@code 'UNKNOWN'} when the city is not in the table.
191	     */
192	    public String getLocality() {
193	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
194	    }
195	
196	    /**
197	     * The owner's membership level, a number from 1 to 3 determined on creation: it starts at 1,
198	     * gains 1 when an email is present, gains 1 when namesakeCount is 0, and is capped at 3.
199	     * Level 4 is reserved for tenure.
200	     */
201	    public Integer getMembershipLevel() {
202	        int level = 1;
203	        if (this.email != null && !this.email.isEmpty()) {
204	            level++;
205	        }
206	        if (this.namesakeCount != null && this.namesakeCount == 0) {
207	            level++;
208	        }
209	        return Math.min(level, 3);
210	    }
211	
212	    /**
213	     * The owner's preferred contact channel: {@code 'EMAIL'} when an email is present,
214	     * otherwise {@code 'PHONE'}.
215	     */
216	    public String getContactPreference() {
217	        return (this.email != null && !this.email.isEmpty()) ? "EMAIL" : "PHONE";
218	    }
219	
220	    /**
221	     * The owner's identity key: the single derived value used for duplicate detection.
222	     * It joins the normalized (E.164) telephone, the email (already lower-cased, or the
223	     * empty string when absent) and the householdId (or the empty string when the owner
224	     * has no household) with {@code '|'}, e.g. {@code '+61412345678|jane@example.test|3C1A9F2B7D4E'}.
225	     * Two owners are duplicates only when their whole identity keys are equal.
226	     */
227	    public String getIdentityKey() {
228	        String telephonePart = this.telephone == null ? "" : this.telephone;
229	        String emailPart = this.email == null ? "" : this.email;
230	        String householdPart = this.householdId == null ? "" : this.householdId;
231	        return telephonePart + "|" + emailPart + "|" + householdPart;
232	    }
233	
234	    protected Set<Pet> getPetsInternal() {
235	        if (this.pets == null) {
236	            this.pets = new HashSet<>();
237	        }
238	        return this.pets;
239	    }
240	
241	    protected void setPetsInternal(Set<Pet> pets) {
242	        this.pets = pets;
243	    }
244	
245	    public List<Pet> getPets() {
246	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
247	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
248	        return Collections.unmodifiableList(sortedPets);
249	    }
250	
251	    public void setPets(List<Pet> pets) {
252	        this.pets = new HashSet<>(pets);
253	    }
254	
255	    public void addPet(Pet pet) {
256	        getPetsInternal().add(pet);
257	        pet.setOwner(this);
258	    }
259	
260	    /**
261	     * Return the Pet with the given name, or null if none found for this Owner.
262	     *
263	     * @param name to test
264	     * @return true if pet name is already in use
265	     */
266	    public Pet getPet(String name) {
267	        return getPet(name, false);
268	    }
269	
270	    /**
271	     * Return the Pet with the given name, or null if none found for this Owner.
272	     *
273	     * @param name to test
274	     * @return true if pet name is already in use
275	     */
276	    public Pet getPet(String name, boolean ignoreNew) {
277	        name = name.toLowerCase();
278	        for (Pet pet : getPetsInternal()) {
279	            if (!ignoreNew || !pet.isNew()) {
280	                String compName = pet.getName();
281	                compName = compName.toLowerCase();
282	                if (compName.equals(name)) {
283	                    return pet;
284	                }
285	            }
286	        }
287	        return null;
288	    }
289	
290	    public Pet getPet(Integer petId) {
291	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
292	    }
293	
294	    @Override
295	    public String toString() {
296	        return new ToStringCreator(this)
297	
298	            .append("id", this.getId())
299	            .append("new", this.isNew())
300	            .append("lastName", this.getLastName())
301	            .append("firstName", this.getFirstName())
302	            .append("address", this.address)
303	            .append("city", this.city)
304	            .append("telephone", this.telephone)
305	            .append("email", this.email)
306	            .toString();
307	    }
308	}
